SELECT 'knowledge_categories' AS entity, COUNT(*) AS seeded_rows
FROM "knowledge_categories"
WHERE "slug" IN ('maintenance', 'property-value', 'insurance', 'climate', 'safety', 'home-finance', 'buying-selling', 'seasonal-care')
UNION ALL
SELECT 'knowledge_tags', COUNT(*)
FROM "knowledge_tags"
WHERE "slug" IN ('roof-age', 'hvac-age', 'water-heater', 'plumbing', 'electrical', 'foundation', 'insulation', 'windows', 'appliances', 'curb-appeal', 'renovations', 'energy-efficiency', 'deferred-maintenance', 'neighborhood-trends', 'school-quality', 'marketability', 'climate-risk', 'water-damage', 'fire-risk', 'storm-risk', 'mold-risk', 'safety-hazards', 'maintenance-backlog', 'insurance-costs', 'maintenance-costs', 'resale-value', 'unexpected-repairs', 'aging-systems', 'premium-increases', 'first-time-homeowner', 'long-term-owner', 'seller', 'buyer', 'budget-conscious')
UNION ALL
SELECT 'product_tools', COUNT(*)
FROM "product_tools"
WHERE "key" IN ('VALUE_TRACKER', 'BREAK_EVEN', 'BUDGET_PLANNER', 'CAPITAL_TIMELINE', 'CLIMATE_RISK', 'COST_EXPLAINER', 'COST_GROWTH', 'COST_VOLATILITY', 'COVERAGE_INTELLIGENCE', 'COVERAGE_OPTIONS', 'DIY', 'DO_NOTHING_SIMULATOR', 'DOCUMENT_VAULT', 'EMERGENCY_HELP', 'ENERGY_AUDIT', 'FINANCING', 'GUIDANCE_OVERVIEW', 'HIDDEN_ASSET_FINDER', 'HOA_COMPLIANCE', 'HOME_DIGITAL_TWIN', 'HOME_DIGITAL_WILL', 'HOME_EVENT_RADAR', 'HOME_GAZETTE', 'HOME_HABIT_COACH', 'RENOVATION_RISK_ADVISOR', 'HOME_RISK_REPLAY', 'HOME_SAVINGS_CHECK', 'HOME_TIMELINE', 'INSPECTION_HUB', 'INSURANCE_TREND', 'MATERIAL_SPECS', 'HOME_UPGRADES', 'MORTGAGE_REFINANCE_RADAR', 'NEGOTIATION_SHIELD', 'NEIGHBORHOOD_CHANGE_RADAR', 'APPLIANCE_ORACLE', 'PERMITS', 'PLANT_ADVISOR', 'PRICE_FINALIZATION', 'PROJECT_TRACKER', 'PROPERTY_TAX', 'QUOTE_COMPARISON', 'REPLACE_REPAIR', 'RESERVE_FUND', 'RISK_PREMIUM_OPTIMIZER', 'SELL_HOLD_RENT', 'SELLER_PREP', 'SERVICE_PRICE_RADAR', 'STATUS_BOARD', 'TAX_APPEAL', 'TRUE_COST', 'VISUAL_INSPECTOR', 'SEASONAL_MAINTENANCE', 'HOME_SCORE_REPORT', 'REPORT_PACK');
